const Suspendable = (Base) => class extends Base {   // mixin: base in,
    #suspended = false;                               // subclass out
    toggle() { this.#suspended = !this.#suspended; }
};
class BallItem extends Suspendable(GameItem) {        // one object, one chain
    #twin = null;
    draw()  { ... }
    click() { this.toggle(); this.#twin?.applySuspend(this.suspended); }
}
